INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(440046, 40971, 6900, '<td valign="top">*crying, scared, hides under the bed*  OMG I''m going to have nightmares for sure!!!</td>', '*crying, scared, hides under the bed*  OMG I''m going to have nightmares for sure!!!', '2003-10-06 01:06:15.000000', NULL, 1),
(440048, 40973, 8970, '<td valign="top">So you want to go to Cornell?  I loved that clock tower, I have pictures of it from all different angle, at all didn''t times of day.  That''s an interesting framing of the building.  I take it that this is taken from the dorms at the bottom of the slope on the upper floor?  Most people probably won''t know what school that is from though, unless they have been there.</td>', 'So you want to go to Cornell?  I loved that clock tower, I have pictures of it from all different angle, at all didn''t times of day.  That''s an interesting framing of the building.  I take it that this is taken from the dorms at the bottom of the slope on the upper floor?  Most people probably won''t know what school that is from though, unless they have been there.', '2003-10-06 01:08:24.000000', NULL, 1),
(440049, 40741, 7350, '<td valign="top">The lack of vibrant color really brings out your idea of death here.  8 from me.</td>', 'The lack of vibrant color really brings out your idea of death here.  8 from me.', '2003-10-06 01:08:28.000000', NULL, 1),
(440052, 40529, 327, '<td valign="top">Nice clear, clean shot of the moon.</td>', 'Nice clear, clean shot of the moon.', '2003-10-06 01:10:18.000000', NULL, 1),
(440053, 40834, 12661, '<td valign="top">The shadowing throws this photo off a bit, particularly that cast by the nose. Nonetheless, an interesting shot but it says "pensive" more than "dreaming".</td>', 'The shadowing throws this photo off a bit, particularly that cast by the nose. Nonetheless, an interesting shot but it says "pensive" more than "dreaming".', '2003-10-06 01:11:07.000000', NULL, 1),
(440055, 40976, 4493, '<td valign="top">This is soooo Shining! Nice job!</td>', 'This is soooo Shining! Nice job!', '2003-10-06 01:12:18.000000', NULL, 1),
(440056, 40841, 12661, '<td valign="top">Those don''t look like normal shark teeth. Then again, that doesn''t mean it isn''t scary.</td>', 'Those don''t look like normal shark teeth. Then again, that doesn''t mean it isn''t scary.', '2003-10-06 01:12:23.000000', NULL, 1),
(440057, 40936, 327, '<td valign="top">I like this, the light, the girl, the pose, the focus, the tone. Just find the crop a bit tight, but that is minor in such a good shot. Very nice.</td>', 'I like this, the light, the girl, the pose, the focus, the tone. Just find the crop a bit tight, but that is minor in such a good shot. Very nice.', '2003-10-06 01:12:24.000000', NULL, 1),
