(440465, 40934, 8522, '<td valign="top">Shame that the picture needs the title to be shoehorned into the challenge as it''s a good picture, capturing an effective expression on the bear''s face. We don''t even see any evidence of the bear''s captivity. 5</td>', 'Shame that the picture needs the title to be shoehorned into the challenge as it''s a good picture, capturing an effective expression on the bear''s face. We don''t even see any evidence of the bear''s captivity. 5', '2003-10-06 09:28:31.000000', NULL, 1),
