(441085, 40925, 11506, '<td valign="top">This is a really nice shot.  Almost perfect but you''ve got two sunspots just left of the center.   Otherwise, good job.</td>', 'This is a really nice shot.  Almost perfect but you''ve got two sunspots just left of the center.   Otherwise, good job.', '2003-10-06 21:30:23.000000', NULL, 1),
(441086, 40855, 12448, '<td valign="top">Not sure of the concept you''re going for.  The shot is clear, sharp and the colors are okay, seem slightly off to me, could be my screen  and I personally am not crazy about the angle but that could be part of your concept!</td>', 'Not sure of the concept you''re going for.  The shot is clear, sharp and the colors are okay, seem slightly off to me, could be my screen  and I personally am not crazy about the angle but that could be part of your concept!', '2003-10-06 21:31:27.000000', NULL, 1),
(441088, 40976, 11506, '<td valign="top">Reminds me of the movie The Shining.  Eriee!</td>', 'Reminds me of the movie The Shining.  Eriee!', '2003-10-06 21:32:15.000000', NULL, 1),
(441090, 40755, 11506, '<td valign="top">This is absoutly stunning.  I don''t know how it relates to a dream that much, but the sheer awesomeness of this shot overrides all of that.  WOW.  I''m speechless.</td>', 'This is absoutly stunning.  I don''t know how it relates to a dream that much, but the sheer awesomeness of this shot overrides all of that.  WOW.  I''m speechless.', '2003-10-06 21:34:03.000000', NULL, 1),
