(441946, 40445, 11800, '<td valign="top">I like this.  The picture is a good solid shot. Changing the colors really enhances it. Good idea clearly expressed. 7</td>', 'I like this.  The picture is a good solid shot. Changing the colors really enhances it. Good idea clearly expressed. 7', '2003-10-08 00:07:05.000000', NULL, 1),
(441947, 40893, 11800, '<td valign="top">Like the cartoon colors, but what is it?</td>', 'Like the cartoon colors, but what is it?', '2003-10-08 00:10:22.000000', NULL, 1),
(441950, 40637, 11800, '<td valign="top">Oh my. That is a nightmare isn''t it! Did you enhance the noise to make it more dramatic? I think everyone here can relate to this one.</td>', 'Oh my. That is a nightmare isn''t it! Did you enhance the noise to make it more dramatic? I think everyone here can relate to this one.', '2003-10-08 00:13:56.000000', NULL, 1),
(441955, 40658, 11800, '<td valign="top">Funny. Well thought out. Don''t see enough of the hand on the left side, where I would imagine she is holding something that wil complete the title.  Just can''t make it out and that is really frustrating.  More so, because it''s a pretty good attempt.</td>', 'Funny. Well thought out. Don''t see enough of the hand on the left side, where I would imagine she is holding something that wil complete the title.  Just can''t make it out and that is really frustrating.  More so, because it''s a pretty good attempt.', '2003-10-08 00:23:10.000000', NULL, 1),
(441958, 40658, 4494, '<td valign="top">Hahahaaa, that is a nightmare look on her face!  Great job.  Don''t really understand the Title though.</td>', 'Hahahaaa, that is a nightmare look on her face!  Great job.  Don''t really understand the Title though.', '2003-10-08 00:29:25.000000', NULL, 1),
(441960, 40960, 11800, '<td valign="top">Really good. I like the rings being so prominent on both their hands. The items on the mantel could be a tad darker, they look washed out from the window light.</td>', 'Really good. I like the rings being so prominent on both their hands. The items on the mantel could be a tad darker, they look washed out from the window light.', '2003-10-08 00:29:44.000000', NULL, 1),
